import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import {DEG,radecVector,vectorRaDec,angularSeparation,observationFrame,observeStar,wrapDeg} from '../src/astronomy.mjs';
import {projectPerspective,projectAllSky} from '../src/projection.mjs';
import {createDiagnosticDiffuseSampler,observeDiffuseDirection,horizontalToDiffuseJ2000,diffuseRayToMap,renderDiagnosticDiffuse} from '../src/diffuse-map.mjs';
const near=(a,b,t=1e-9)=>assert.ok(Math.abs(a-b)<=t,`${a} vs ${b}, tol ${t}`);
const frameObserver={utcMs:Date.UTC(2026,9,4,3),latDeg:28.54,lonDeg:-81.38};
const controlled={utcMs:Date.UTC(2000,0,1,12),latDeg:0,lonDeg:0,meanOnly:true,ttMinusUtcSeconds:0,pressureHpa:0}; // analytic profile, not an observed clock
const camera={type:'camera',width:32,height:48,azDeg:180,altDeg:45,fovYDeg:70,rollDeg:0};
function fixture(w=16,h=8){return {schema:'salah-real-sky/diffuse-map/1',id:'explicit-synthetic-test-fixture',role:'test-fixture',productionAdmissible:false,sourceSha256:'a'.repeat(64),frame:'mean-equatorial-J2000',epochJyear:2000,quantity:'relative-V0-flux-per-steradian',grid:{type:'equirectangular-cell-centred',width:w,height:h,lonOriginDeg:0,latOriginDeg:-90,lonStepDeg:360/w,latStepDeg:180/h},values:Array(w*h).fill(1),validMask:Array(w*h).fill(1)};}
const actual=()=>JSON.parse(fs.readFileSync(new URL('../data/diffuse/hyg-residual-128x64.json',import.meta.url),'utf8'));

test('real retained diagnostic asset validates without becoming a survey',()=>{const s=createDiagnosticDiffuseSampler(actual());assert.equal(s.productionAdmissible,false);assert.equal(s.width,128);assert.equal(s.diagnosticOnly,true);near(s.totalRelativeV0Flux,59.89915957353178,1e-10);});
test('constant field remains constant at seam and both poles',()=>{const s=createDiagnosticDiffuseSampler(fixture());for(const ra of [-360,0,33,359.999,360,720])for(const de of [-90,-89.99,-45,0,89.99,90])near(s.sample(ra,de).value,1);});
test('cell-centre sampling returns the retained cell value',()=>{const a=fixture();a.values=a.values.map((_,i)=>i);const s=createDiagnosticDiffuseSampler(a);for(let j=0;j<8;j++)for(let i=0;i<16;i++)near(s.sample((i+.5)*22.5,-90+(j+.5)*22.5).value,a.values[j*16+i],1e-10);});
test('periodic seam interpolates neighbouring first and last columns',()=>{const a=fixture();a.values=a.values.map((_,i)=>i%16);const s=createDiagnosticDiffuseSampler(a);near(s.sample(0,-11.25).value,7.5);near(s.sample(360,-11.25).value,7.5);});
test('longitude variation vanishes at a pole',()=>{const a=fixture();a.values=a.values.map((_,i)=>i%16);const s=createDiagnosticDiffuseSampler(a);for(const ra of [0,71,179,273]){near(s.sample(ra,90).value,7.5);near(s.sample(ra,-90).value,7.5);}});
test('pole limits are continuous for actual diagnostic',()=>{const s=createDiagnosticDiffuseSampler(actual());for(const ra of [0,15,90,180,355])for(const pole of [-90,90])near(s.sample(ra,pole).value,s.sample(ra,pole-Math.sign(pole)*1e-8).value,1e-6);});
test('missing value remains unavailable, not zero or an inpainted estimate',()=>{const a=fixture();a.validMask[3*16+3]=0;a.values[3*16+3]=null;const s=createDiagnosticDiffuseSampler(a);const q=s.sample(3.5*22.5,-90+3.5*22.5);assert.equal(q.value,null);assert.equal(q.defined,false);near(q.supportFraction,0);});
test('partial support is not renormalised into full brightness',()=>{const a=fixture();a.validMask[3*16+3]=0;a.values[3*16+3]=0;const q=createDiagnosticDiffuseSampler(a).sample(4*22.5,-90+3.5*22.5);assert.equal(q.value,null);near(q.supportFraction,.5);near(q.availableWeightedValue,.5);});
test('unavailable cap data does not become a complete pole',()=>{const a=fixture();a.validMask[0]=0;a.values[0]=null;const q=createDiagnosticDiffuseSampler(a).sample(0,-90);assert.equal(q.defined,false);near(q.supportFraction,15/16);});
test('sampler copies data and does not depend on later caller mutations',()=>{const a=fixture();const s=createDiagnosticDiffuseSampler(a);a.values.fill(100);a.validMask.fill(0);near(s.sample(0,0).value,1);});
test('production claims, unknown role and unsupported units are refused',()=>{for(const patch of [{productionAdmissible:true},{role:'observed-survey'},{quantity:'infrared-100um'},{frame:'galactic'},{epochJyear:1950}])assert.throws(()=>createDiagnosticDiffuseSampler({...fixture(),...patch}));});
test('bad numeric values and contradictory masks are refused',()=>{for(const v of [-1,NaN,Infinity,'1',null]){const a=fixture();a.values[0]=v;assert.throws(()=>createDiagnosticDiffuseSampler(a));}const a=fixture();a.validMask[0]=0;assert.throws(()=>createDiagnosticDiffuseSampler(a));});
test('bad shapes and finite grid spacing are refused',()=>{const a=fixture();a.values.pop();assert.throws(()=>createDiagnosticDiffuseSampler(a));for(const step of [undefined,NaN,'22.5',0]){const b=fixture();b.grid.lonStepDeg=step;assert.throws(()=>createDiagnosticDiffuseSampler(b));}});
test('declared total cannot silently disagree with array',()=>{assert.throws(()=>createDiagnosticDiffuseSampler({...fixture(),totalRelativeV0Flux:2}));});
test('all-sphere constant radiance has 4pi integrated flux',()=>near(createDiagnosticDiffuseSampler(fixture()).totalRelativeV0Flux,4*Math.PI,1e-12));
test('map coordinates reject nonfinite directions and impossible declinations',()=>{const s=createDiagnosticDiffuseSampler(fixture());for(const p of [[NaN,0],[0,91],[0,-91],['0',0]])assert.throws(()=>s.sample(...p));});
test('controlled analytic transit and rising-east orientation anchors',()=>{const f=observationFrame(controlled);const h=observeDiffuseDirection(radecVector(f.lstDeg,0),f);near(h.altDeg,90,1e-6);const e=observeDiffuseDirection(radecVector(f.lstDeg+90,0),f);near(e.altDeg,0,1e-8);near(e.azDeg,90);});
test('controlled north pole is at observer latitude',()=>{for(const lat of [-75,-20,0,24.47,64.15,90]){const f=observationFrame({...controlled,latDeg:lat});near(observeDiffuseDirection([0,0,1],f).altDeg,lat,1e-7);}});
test('controlled inverse horizon east has RA=LST+90 at equator',()=>{const f=observationFrame(controlled);const v=vectorRaDec(horizontalToDiffuseJ2000({altDeg:0,azDeg:90},f));near(wrapDeg(v.raDeg-f.lstDeg),90,1e-9);near(v.decDeg,0);});
test('full frame round trips directions across locations, dates and sky poles',()=>{for(const year of [1900,2000,2026,2100])for(const lat of [-90,-33.87,0,28.54,64.15,90]){const f=observationFrame({...frameObserver,utcMs:Date.UTC(year,5,21),latDeg:lat});for(const ra of [0,90,180,359.9])for(const de of [-90,-50,0,66,90]){const v=radecVector(ra,de),h=observeDiffuseDirection(v,f),back=horizontalToDiffuseJ2000(h,f);assert.ok(angularSeparation(v,back)<2e-6);}}});
test('fixed infinite-distance catalogue direction follows exactly the shared astrometry',()=>{const f=observationFrame(frameObserver);for(const ra of [0,90,215,359])for(const de of [-80,0,75]){const s={raDeg:ra,decDeg:de,epochJyear:2000,pmRaCosDecMasYr:0,pmDecMasYr:0,distancePc:null,radialVelocityKmS:null};const a=observeStar(s,f),b=observeDiffuseDirection(radecVector(ra,de),f);near(a.altDeg,b.altDeg,1e-10);near(a.azDeg,b.azDeg,1e-9);}});
test('inverse uses aberration as well as precession-nutation',()=>{const f=observationFrame({...frameObserver,velocityOverC:[.004,-.002,.001]});const v=radecVector(12,35),h=observeDiffuseDirection(v,f);assert.ok(angularSeparation(v,horizontalToDiffuseJ2000(h,f))<1e-8);});
test('optional refraction is inverted rather than applied a second time',()=>{const base=observationFrame(frameObserver);for(const alt of [0,1,5,30,70,89.95])for(const az of [0,90,230]){const v=horizontalToDiffuseJ2000({altDeg:alt,azDeg:az},base);const f=observationFrame({...frameObserver,pressureHpa:1010,temperatureC:10}),app=observeDiffuseDirection(v,f);assert.ok(app.altDeg>=alt-1e-7);assert.ok(angularSeparation(v,horizontalToDiffuseJ2000(app,f))<1e-7);}});
test('map parallax is not borrowed from a nearby star',()=>{const v=radecVector(150,35),a=observeDiffuseDirection(v,{...frameObserver,parallax:false}),b=observeDiffuseDirection(v,{...frameObserver,parallax:true});near(a.altDeg,b.altDeg);near(a.azDeg,b.azDeg);});
test('perspective forward/inverse registration respects camera roll',()=>{const f=observationFrame(frameObserver);for(const roll of [0,45,90,180]){const view={...camera,rollDeg:roll};for(const h of [{altDeg:45,azDeg:180},{altDeg:55,azDeg:175}]){const p=projectPerspective(h,view),ray=diffuseRayToMap(p.x,p.y,view,f),expect=horizontalToDiffuseJ2000(h,f);assert.ok(angularSeparation(ray.j2000,expect)<1e-8);}}});
test('all-sky registration preserves east-left handedness',()=>{const f=observationFrame(frameObserver),v={type:'allsky',width:100,height:100};const p=projectAllSky({altDeg:30,azDeg:90},v);assert.ok(p.x<50);const ray=diffuseRayToMap(p.x,p.y,v,f);near(ray.horizontal.azDeg,90,1e-8);});
test('below horizon rays are separate, not sampled as celestial zeros',()=>{const ray=diffuseRayToMap(50,1,{type:'allsky',width:100,height:100},frameObserver);assert.equal(ray.aboveHorizon,false);assert.equal(ray.j2000,null);});
test('constant diagnostic render is stable across fractional and integer DPR',()=>{const s=createDiagnosticDiffuseSampler(fixture());for(const dpr of [1,1.37,2,3]){const r=renderDiagnosticDiffuse(s,frameObserver,camera,{dpr});assert.equal(r.width,Math.round(32*dpr));for(let i=0;i<r.radiance.length;i++)if(r.skyFraction[i]===1)near(r.radiance[i],1,1e-10);}});
test('footprint supersampling preserves a constant surface field',()=>{const s=createDiagnosticDiffuseSampler(fixture());for(const n of [1,2,4]){const r=renderDiagnosticDiffuse(s,frameObserver,camera,{samplesPerAxis:n});for(let i=0;i<r.radiance.length;i++)if(r.skyFraction[i]===1)near(r.radiance[i],1,1e-10);}});
test('time and longitude change map directions; backward seek restores',()=>{const s=createDiagnosticDiffuseSampler(actual());const a=renderDiagnosticDiffuse(s,frameObserver,camera),b=renderDiagnosticDiffuse(s,{...frameObserver,utcMs:frameObserver.utcMs+21600000},camera),c=renderDiagnosticDiffuse(s,frameObserver,camera),d=renderDiagnosticDiffuse(s,{...frameObserver,lonDeg:39.61},camera);assert.notDeepEqual(a.radiance,b.radiance);assert.deepEqual(a.radiance,c.radiance);assert.notDeepEqual(a.radiance,d.radiance);});
test('render reports data holes without silently darkening them',()=>{const a=fixture();a.validMask.fill(0);a.values.fill(null);const r=renderDiagnosticDiffuse(createDiagnosticDiffuseSampler(a),frameObserver,camera);assert.ok(r.missingPixels>0);assert.equal(r.missingPixels,r.skyPixels);});
test('invalid observer, oversize raster and sample counts are refused',()=>{const s=createDiagnosticDiffuseSampler(fixture());assert.throws(()=>renderDiagnosticDiffuse(s,{...frameObserver,latDeg:91},camera));assert.throws(()=>renderDiagnosticDiffuse(s,frameObserver,{...camera,width:2048,height:2048},{dpr:3}));assert.throws(()=>renderDiagnosticDiffuse(s,frameObserver,camera,{samplesPerAxis:5}));});
test('diagnostic raster never claims physical composition or source admission',()=>{const r=renderDiagnosticDiffuse(createDiagnosticDiffuseSampler(fixture()),frameObserver,camera);assert.equal(r.productionAdmissible,false);assert.equal(r.physicalComposition,'NOT_IMPLEMENTED_IN_CP7_3');assert.equal(r.linear,undefined);});
test('sampling implementation has no procedural population or private clock',()=>{const source=fs.readFileSync(new URL('../src/diffuse-map.mjs',import.meta.url),'utf8');assert.ok(!source.includes('Math.random('));assert.ok(!source.includes('Date.now('));assert.ok(!source.includes('setInterval('));});
